    `retain` defaults to empty. Malformed lists are rejected here; an ID that is
    a valid string but was never applied is rejected here too, because that needs
    the persisted journal and no other module is allowed to own it. Repeated IDs
    are harmless; the value is consumed as a set.
    """
    retained = set(_id_list(request.get("retain", []), "invalid-retain"))
    if not retained <= applied:
        raise JournalError("invalid-retain")
    return retained


# G3: the batch entrypoint. A batch names its own action; each element is a
# single rollback request with `action` omitted (the batch supplies it). The
# action name itself is policy's to know (policy.BATCH_ACTION); these shapes
# are journal concerns. A structurally invalid element carries its index as a
# second error argument so the caller can report `requestIndex`.
BATCH_FIELDS = {"action", "requests"}
BATCH_ITEM_FIELDS = {"environment", "budget", "changes", "applied", "retain"}
BATCH_MIN_ITEMS = 1
BATCH_MAX_ITEMS = 128


def read_batch(request):
    """Validate the batch envelope and return its element objects, in order.

    The envelope check is `invalid-batch`; a structurally invalid element is
    `invalid-batch-item`. Only the shape is checked here -- value errors inside
    an element belong to its own policy/journal/planner validation and keep
    their single-request error codes. A structural element error carries the
    index of the offending element.
    """
    if not isinstance(request, dict) or set(request) != BATCH_FIELDS:
        raise JournalError("invalid-batch")
    requests = request["requests"]
    if not isinstance(requests, list) or not BATCH_MIN_ITEMS <= len(requests) <= BATCH_MAX_ITEMS:
        raise JournalError("invalid-batch")
    for index, item in enumerate(requests):
        if not isinstance(item, dict) or not set(item) <= BATCH_ITEM_FIELDS:
            raise JournalError("invalid-batch-item", index)
    return requests

