    """Turn one batch element into a single rollback request.

    The element must not name an action of its own: the batch entrypoint sets
    it. An element asking for anything else is structurally invalid for a
    batch -- a batch element cannot smuggle in a plan -- and fails with
    `invalid-batch-item` at its own index.
    """
    if item.get("action", "rollback") != "rollback":
        raise JournalError("invalid-batch-item", index)
    request = {key: value for key, value in item.items() if key != "action"}
    request["action"] = "rollback"
    return request


def plan_batch(request):
    """Execute a G3 batch: every element is an independent rollback request.

    Items are processed in order, each with its own changes, journal and retain
    set. The first failing item ends the batch with its own error code and index;
    no partial results are emitted.
    """
    try:
