# ---------------------------------------------------------------------------
# G4 batch rollback
# ---------------------------------------------------------------------------

BATCH_ACTION = "rollback-many"
# G4 top-level shape: `action`, `limit` and `requests` only, `limit` mandatory.
BATCH_TOP_FIELDS = {"action", "limit", "requests"}
BATCH_ITEM_FIELDS = {"environment", "budget", "changes", "applied", "retain", "operation_id"}
BATCH_MIN_ITEMS = 1
BATCH_MAX_ITEMS = 128


def batch_failure(code, index):
    """Atomic batch error: no partial results and no partial units."""
    return {"status": "error", "error": code, "requestIndex": index, "results": [], "units": 0}


def is_batch(request):
    return isinstance(request, dict) and request.get("action") == BATCH_ACTION


def _read_limit(request):
    if set(request) != BATCH_TOP_FIELDS:
        raise JournalError("invalid-batch")
