    """Check only the batch envelope: a list of 1..128 items.

    Item shapes are deliberately *not* scanned here. G4 orders decisions by
    request position, so a later item's shape problem must not pre-empt an
    earlier item's real domain failure; that interleaving only works if each
    item is checked inside the main loop.
    """
    requests = request["requests"]
    if not isinstance(requests, list) or not BATCH_MIN_ITEMS <= len(requests) <= BATCH_MAX_ITEMS:
