    Raises JournalError carrying the G4 shape code; the caller attaches the
    request index, because only the caller knows where the item came from.
    """
    if not isinstance(item, dict) or set(item) - BATCH_ITEM_FIELDS:
        raise JournalError("invalid-batch-item")
