    """Type-tagged rendering of JSON request data, used to compare retries.

    Object key order is irrelevant, so keys are sorted. Array order matters, so
    arrays are rendered positionally. JSON numbers and booleans must never
    compare equal (Python's True == 1 and 1.0 == 1), so every scalar carries a
    JSON type tag and the result is tuples, never dicts.
    """
    if isinstance(value, dict):
        return ("object", tuple(sorted((key, _canonical(item)) for key, item in value.items())))
    if isinstance(value, list):
        return ("array", tuple(_canonical(item) for item in value))
    if isinstance(value, bool):
        return ("boolean", value)
    if isinstance(value, int):
        return ("integer", value)
    if isinstance(value, float):
        return ("number", value)
    if isinstance(value, str):
        return ("string", value)
    if value is None:
        return ("null", None)
    return ("unknown", repr(value))


def rollback_many(request):
    """G4 batch rollback: one response for the whole batch, never partial.

    Decision order, per CHANGE-G2.md G4 and modules/architecture.md: top-level
    shape and `limit`, then per-item structure and operation_id, then duplicate
    or conflict on operation_id, then the G2 work for each new ID. Only once the
    whole batch has passed that does the batch limit apply, so a real per-item
    failure always outranks batch-limit-exceeded. The batch `limit` applies to
    this endpoint only; a single G2 rollback is never capped by it.
    """
    try:
        limit = _read_limit(request)
        items = _read_items(request)
    except JournalError as exc:
        return batch_failure(str(exc.args[0]), None)
    # operation_id -> canonical data of its first appearance, kept in first
    # appearance order because results follow it: a retry adds no second slot.
    seen = {}
    results = []
    for index, item in enumerate(items):
        # Structure and operation_id of item i are checked here, in request
        # order, immediately before its duplicate/conflict test and its G2
        # work -- never in a batch-wide pre-pass -- so the first real failure in
        # position order is the one reported and it outranks the batch limit.
        try:
            operation_id, inner = _item_request(item)
            fingerprint = _canonical(inner)
        except (PolicyError, JournalError) as exc:
            return batch_failure(str(exc), index)
        previous = seen.get(operation_id)
        if previous is not None:
            if previous != fingerprint:
                # Same ID, different data: an ambiguous retry cannot be resolved
                # silently, so the batch stops and names the later item.
                return batch_failure("conflicting-operation", index)
            # Identical retry: the first result already covers it and it is
            # billed once, so nothing is computed and nothing is appended.
            continue
        seen[operation_id] = fingerprint
        try:
            actions, units = execute(inner)
        except (PolicyError, JournalError) as exc:
            return batch_failure(str(exc), index)
        # operationId echoes the caller's operation_id so a result can be
        # matched back to the request that produced it.
        results.append({"actions": actions, "units": units, "operationId": operation_id})
    units = sum(result["units"] for result in results)
    if units > limit:
        return batch_failure("batch-limit-exceeded", None)
    return {"status": "ok", "results": results, "units": units}


def dispatch(request):
    """Route a decoded request; the entrypoint keeps transport concerns only."""
    if is_batch(request):
        return rollback_many(request)
    return plan(request)

