            return batch_failure(code, position)
        if kind == "retry":
            actions, units = computed[source]
        else:
            # The batch entrypoint owns the action: items cannot opt into plan.
            single = dict(items[position])
            single.pop("operation_id", None)
            single["action"] = "rollback"
