                actions, units = evaluate(single)
            except (PolicyError, JournalError) as exc:
                return batch_failure(str(exc), position)
            computed[position] = (actions, units)
            # A retry is billed once, so only a first occurrence adds to the total.
            total += units
        results.append(
            {"operationId": operation_id, "actions": actions, "units": units}
        )

    # G4: the batch ceiling covers the deduplicated operations actually
    # performed, and is checked only once the whole batch has been accepted.
    # Equalling the limit is allowed; the single G2 rollback stays uncapped.
