"""Compose policy and journal data into a plan."""
import heapq

from journal import (
    BATCH_ACTIONS,
    JournalError,
    read_applied,
    read_batch,
    read_batch_item,
    read_changes,
    read_retain,
)
from policy import PolicyError, limit_for, rollback_decision


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def build_graph(changes):
    """Index changes by ID and verify that every dependency target exists."""
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for target in row["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
    return by_id


def topological_order(by_id):
    """Kahn's algorithm with lexicographic tie-breaking among eligible changes.

    The order covers every change, applied or not, so a cycle or a dangling
    reference is detected even when the emitted action list would be empty.
    """
    pending = {key: len(by_id[key]["depends_on"]) for key in by_id}
    dependents = {key: [] for key in by_id}
    for key in by_id:
        for target in by_id[key]["depends_on"]:
            dependents[target].append(key)
    eligible = [key for key, count in pending.items() if not count]
    heapq.heapify(eligible)
    order = []
    while eligible:
        key = heapq.heappop(eligible)
        order.append(key)
        for dependent in dependents[key]:
            pending[dependent] -= 1
            if not pending[dependent]:
                heapq.heappush(eligible, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(by_id, applied, retained):
    """`retained` plus the transitive dependencies it needs, limited to applied ones.

    A retained change must stay installed, so whatever it depends on must stay
    too. An unapplied dependency is not installed and so is never kept, but the
    walk continues through it: c -> b(unapplied) -> a still keeps a when c is
    retained, because a is installed and c still needs it. G3 states the same
    rule for the batch form -- "trace the whole dependency graph, then exclude
    only applied ancestors" -- so both forms share this one function.

    The walk is an explicit stack, not recursion: G3 requires single items of
    2,000+ changes whose dependencies form long chains, and a recursive walk
    would overflow the interpreter stack on those inputs. Each node is expanded
    at most once and `keep` tracks expanded nodes, so cycles (rejected earlier
    by `topological_order`, but guarded here anyway) cannot loop forever.
    """
    keep = set(retained)
    expanded = set()
    stack = list(keep)
    while stack:
        key = stack.pop()
        if key in expanded:
            continue
        expanded.add(key)
        for target in by_id[key]["depends_on"]:
            # Only applied ancestors are kept; unapplied ones are still walked
            # so an applied change behind them can be found.
            if target in applied and target not in keep:
                keep.add(target)
            if target not in expanded:
                stack.append(target)
    return keep


def rollback_actions(by_id, order, applied, retained):
    """Applied IDs in reverse execution order, minus retained changes and their needs."""
    keep = retained_closure(by_id, applied, retained)
    return [key for key in reversed(order) if key in applied and key not in keep]


def rollback_order(item):
    """Replay one batch item as a rollback and return its actions and units.

    The batch entrypoint fixes every item to rollback, so the policy decision is
    built directly here instead of via `policy.limit_for`: that function reads
    `action` from the request, and a batch item is not allowed to carry one.
    `limit=None` mirrors single-item rollback -- the budget is validated but
    never caps a rollback (G2 quota applies to staging plans only). Environment
    and budget go through `policy.rollback_decision`, the shared rollback rule,
    so `invalid-environment` / `production-frozen` / `invalid-budget` match the
    single-item path exactly. Every other field is read by the same
    journal/planner helpers, in the same order (changes, then applied, then
    graph, then retention as the last step), so a batch item reports exactly the
    business code it would report on its own.

    No state is shared between items: the readers, the graph and the closure
    are rebuilt per call, so IDs, applied journals and retain sets of different
    items cannot influence each other.
    """
    rollback_decision(item)
    changes = read_changes(item.get("changes"))
    applied = read_applied(item.get("applied", []))
    by_id = build_graph(changes)
    if not applied <= by_id.keys():
        raise JournalError("unknown-dependency")
    order = topological_order(by_id)
    retained = read_retain(item, applied)
    actions = rollback_actions(by_id, order, applied, retained)
    units = sum(by_id[key]["units"] for key in actions)
    return {"actions": actions, "units": units}


def batch_failure(code, index):
    """G3 failure shape.

    Distinct from `failure()`: a batch error carries `requestIndex` and the key
    `results` instead of `actions`, and adding that to the shared function would
    leak extra keys into single-item errors. `index` is None when the envelope
    itself is malformed and no item can be named.
    """
    return {
        "status": "error",
        "error": code,
        "requestIndex": index,
        "results": [],
        "units": 0,
    }


def plan_batch(request):
    """Rollback-many: validate the envelope, then replay items one at a time."""
    try:
        # Envelope first: structural problems of the batch are `invalid-batch`
        # with a null index, even if an element is also malformed.
        items = read_batch(request)
    except JournalError as exc:
        return batch_failure(str(exc), None)
    results = []
    total = 0
    for index, item in enumerate(items):
        try:
            # Structural shape is owned by the batch (invalid-batch-item); the
            # business errors raised afterwards keep their own codes.
            read_batch_item(item)
            result = rollback_order(item)
        except (JournalError, PolicyError) as exc:
            # First failure ends the batch: the real code and the actual index
            # are reported and the accumulated results are dropped, so a batch
            # never returns partial output.
            return batch_failure(str(exc), index)
        results.append(result)
        total += result["units"]
    return {"status": "ok", "results": results, "units": total}


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    if request.get("action") in BATCH_ACTIONS:
        # G3 shape: `{status, results, units}` on success and
        # `{status, error, requestIndex, results, units}` on failure. Neither
        # reuses the single-item shapes, so the old contract is untouched.
        return plan_batch(request)
    try:
        # The environment/action/budget check comes first so a frozen production
        # request is reported before any graph or change validation runs.
        policy = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        by_id = build_graph(changes)
        if not applied <= by_id.keys():
            raise JournalError("unknown-dependency")
        order = topological_order(by_id)
        if policy.action == "rollback":
            retained = read_retain(request, applied)
            actions = rollback_actions(by_id, order, applied, retained)
        else:
            actions = [key for key in order if key not in applied]
            if sum(by_id[key]["units"] for key in actions) > policy.limit:
                return failure("budget-exceeded")
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units = sum(by_id[key]["units"] for key in actions)
    return {"status": "ok", "actions": actions, "units": units}

