    reuse IDs but differ in `applied`/`retain` cannot observe each other.
    """
    if not isinstance(request, dict):
        return _invalid_batch()
    if not request.keys() <= {"action", "requests"} or request.get("action") != "rollback-many":
        return _invalid_batch()
    items = request.get("requests")
    if not isinstance(items, list) or not 1 <= len(items) <= BATCH_MAX_ITEMS:
        return _invalid_batch()
    results = []
    total = 0
    for index, item in enumerate(items):
        try:
            read_batch_item(item)
