            item.get("budget"),
            read_changes(item.get("changes")),
            frozenset(read_applied(item.get("applied", []))),
            frozenset(read_retain(item, read_applied(item.get("applied", [])))))


def _read_batch_limit(request):
    """G4 `limit`: required nonnegative integer, booleans excluded.

    Lives here rather than in policy because the batch quota is batch-only: a
    single rollback has no ceiling and must not inherit this one. type() rather
    than isinstance() so `true`/`false` are not read as 1/0.
    """
    limit = request.get("limit")
    if type(limit) is not int or limit < 0:
        raise JournalError("invalid-batch")
    return limit


def rollback_many(request):
    """G4 batch rollback: one ordered list of independent single-rollback bodies.

    G4 splits what G3 did in one pass, because quoting against `limit` and
    deduplicating matters only once every element is known to be a legal request:

    1. Envelope: only `action`/`limit`/`requests`, `limit` a nonnegative integer,
       `requests` an array of 1..128. Any breach is `invalid-batch` + null index.
    2. Structure: every element in request order is checked for item shape and
       `operation_id` (`invalid-batch-item` + its index). This pass is *complete*
       before conflict detection starts, so a malformed late element outranks an
       earlier conflict.
    3. Identity: walk again in request order, keyed by `operation_id`. An equal
       fingerprint (see `_batch_fingerprint`) is a retry -- no result, no charge.
       A different fingerprint under a seen ID is `conflicting-operation` on the
       *later* element, even if that element would also fail on business grounds.
    4. Business: only first occurrences run the G2 checks and graph work, in
       request order; the first real failure ends the batch with its own code and
       index, ahead of any quota verdict.
    5. Quota: only after all of that, the summed units of the non-retry results
       are compared with `limit`. Exceeding it is `batch-limit-exceeded` + null
       index; equal or below submits.

    Every map here is local to one call and no graph, closure or result is cached
    across elements, so two elements reusing IDs but differing in
    `applied`/`retain` cannot observe each other. Only the same `operation_id`
    with identical data is merged, and it is merged as the same operation.

    `request` may be any object at this point and non-objects are simply
    `invalid-batch`: the transport only routes objects labelled
    `rollback-many`, so a direct caller here is already talking batch language.
    """
    if not isinstance(request, dict):
        return _invalid_batch()
    # An element can never widen the batch's action, and the envelope cannot
    # smuggle batch-only keys past this gate, so the whitelist is exact.
    if not request.keys() <= {"action", "limit", "requests"}:
        return _invalid_batch()
    if request.get("action") != "rollback-many":
        return _invalid_batch()
    items = request.get("requests")
    if not isinstance(items, list) or not 1 <= len(items) <= BATCH_MAX_ITEMS:
        return _invalid_batch()
    try:
        limit = _read_batch_limit(request)
    except JournalError:
        return _invalid_batch()

    # Pass 2: structure only, whole batch, before any identity or business work.
    for index, item in enumerate(items):
        try:
            read_batch_item(item)
        except JournalError as exc:
            return _batch_failure(str(exc), index)

    # Pass 3: identity. `first` keeps the first occurrence of each operation in
    # request order and pass 4 bills each of those exactly once; an equal repeat
    # later in the list is a retry and simply produces no result of its own.
    first = {}
    order = []
    for index, item in enumerate(items):
        operation_id = read_operation_id(item)
        try:
            fingerprint = _batch_fingerprint(item)
        except JournalError:
            # Still legal to reach here: shape passed but business data did not.
            # The comparison cannot be made, so the conflict check is skipped and
            # pass 4 reports this element's real domain code in order.
            fingerprint = ("uncomparable", index)
        seen = first.get(operation_id)
        if seen is None:
            first[operation_id] = (index, fingerprint)
            order.append(operation_id)
        elif seen[1] == fingerprint:
            # Retry: same ID, equivalent data. Nothing to add, nothing to charge.
            continue
        else:
            return _batch_failure("conflicting-operation", index)

    # Pass 4: business work for first occurrences only, in request order.
    results = []
    total = 0
    for operation_id in order:
        index = first[operation_id][0]
        try:
            # Rollback by construction: the element's environment is still
            # checked (production stays frozen) and its budget is still
            # validated, but the plan quota never applies to a rollback.
            decision = rollback_decision(items[index])
            if decision.action != "rollback":
                raise PolicyError("unsupported-action")
            actions, by_id = compute_actions(_batch_body(items[index]))
        except (PolicyError, JournalError) as exc:
            return _batch_failure(str(exc), index)
        units = sum(by_id[key]["units"] for key in actions)
        results.append({"actions": actions, "units": units,
                        "operationId": operation_id})
        total += units

    # Pass 5: the batch-only quota, decided last so a real failure always wins.
    if total > limit:
        return _batch_failure("batch-limit-exceeded", None)
    return {"status": "ok", "results": results, "units": total}

