"""JSON transport for the release planner."""
import json
import sys

from planner import plan, rollback_many


def dispatch(request):
    """Route one decoded request to the planner entry that owns it.

    Transport stays a pass-through: this is the only place that looks at a
    request field, and it looks at `action` alone. `rollback-many` is a batch of
    independent requests, so it must reach the batch assembler instead of the
    single-request path -- which would otherwise reject it as
    `unsupported-action`. Every other value, including a non-object, goes to
    `plan` unchanged so G1/G2 codes and ordering are untouched; a non-object is
    guarded here first only because subscripting it would raise.
    """
    if isinstance(request, dict) and request.get("action") == "rollback-many":
        return rollback_many(request)
    return plan(request)


def main():
    try:
        request = json.load(sys.stdin)
    except (ValueError, TypeError):
        result = {"status": "error", "error": "invalid-json", "actions": [], "units": 0}
    else:
        # One input, one JSON line, always exit 0: domain errors are results, not
        # crashes, so an orchestrator reads the batch outcome from stdout alone.
        result = dispatch(request)
    print(json.dumps(result, separators=(",", ":")))


if __name__ == "__main__":
    main()

