"""Compose policy and journal data into a plan."""
import heapq

from journal import (BATCH_ITEM_FIELDS, JournalError, read_applied, read_batch_item,
                     read_changes, read_operation_id, read_retain)
from policy import PolicyError, limit_for, rollback_decision


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def build_graph(changes):
    """Index changes by ID and verify that every dependency target exists."""
    by_id = {row["id"]: row for row in changes}
    for row in changes:
        for target in row["depends_on"]:
            if target not in by_id:
                raise JournalError("unknown-dependency")
    return by_id


def topological_order(by_id):
    """Kahn's algorithm with lexicographic tie-breaking among eligible changes.

    The order covers every change, applied or not, so a cycle or a dangling
    reference is detected even when the emitted action list would be empty.
    """
    pending = {key: len(by_id[key]["depends_on"]) for key in by_id}
    dependents = {key: [] for key in by_id}
    for key in by_id:
        for target in by_id[key]["depends_on"]:
            dependents[target].append(key)
    eligible = [key for key, count in pending.items() if not count]
    heapq.heapify(eligible)
    order = []
    while eligible:
        key = heapq.heappop(eligible)
        order.append(key)
        for dependent in dependents[key]:
            pending[dependent] -= 1
            if not pending[dependent]:
                heapq.heappush(eligible, dependent)
    if len(order) != len(by_id):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(by_id, applied, retained):
    """`retained` plus the transitive dependencies it needs, limited to applied ones.

    The walk and the keep decision are separate (G3). The walk follows *every*
    dependency in the full graph, seen-set guarded, because an unapplied node is
    still a path to installed ancestors: c -> b(unapplied) -> a keeps a when c is
    retained, since a is installed and c still needs it. Stopping the walk at an
    unapplied node would leak a revert of a change that must stay. Only
    `target in applied` puts a node into the result; the seed `retained` is kept
    as given because the caller has already checked it is applied.

    Cost is one pass per visited node, so a batch item stays linear in the graph.
    """
    keep = set(retained)
    seen = set(retained)
    stack = list(retained)
    while stack:
        for target in by_id[stack.pop()]["depends_on"]:
            if target in seen:
                continue
            seen.add(target)
            stack.append(target)
            if target in applied:
                keep.add(target)
    return keep


def rollback_actions(by_id, order, applied, retained):
    """Applied IDs in reverse execution order, minus retained changes and their needs."""
    keep = retained_closure(by_id, applied, retained)
    return [key for key in reversed(order) if key in applied and key not in keep]


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        # The environment/action/budget check comes first so a frozen production
        # request is reported before any graph or change validation runs.
        policy = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied", []))
        by_id = build_graph(changes)
        if not applied <= by_id.keys():
            raise JournalError("unknown-dependency")
        order = topological_order(by_id)
        if policy.action == "rollback":
            retained = read_retain(request, applied)
            actions = rollback_actions(by_id, order, applied, retained)
        else:
            actions = [key for key in order if key not in applied]
            if sum(by_id[key]["units"] for key in actions) > policy.limit:
                return failure("budget-exceeded")
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units = sum(by_id[key]["units"] for key in actions)
    return {"status": "ok", "actions": actions, "units": units}


def compute_actions(request):
    """Validate one request and return (actions, by_id); raise on any domain error.

    `plan` wraps this in the single-request envelope; `rollback_many` reuses it so
    a batch element produces exactly the actions, and exactly the error code, of
    the same body sent as a lone rollback. Every call builds fresh locals from
    its own request -- no cache, no shared mutable graph -- so two batch items
    that reuse IDs or differ only in `applied`/`retain` cannot leak into each
    other. Only `by_id` is returned alongside the actions so the caller can price
    them without re-deriving the per-change units.
    """
    policy = limit_for(request)
    changes = read_changes(request.get("changes"))
    applied = read_applied(request.get("applied", []))
    by_id = build_graph(changes)
    if not applied <= by_id.keys():
        raise JournalError("unknown-dependency")
    order = topological_order(by_id)
    if policy.action == "rollback":
        retained = read_retain(request, applied)
        actions = rollback_actions(by_id, order, applied, retained)
    else:
        actions = [key for key in order if key not in applied]
        if sum(by_id[key]["units"] for key in actions) > policy.limit:
            raise PolicyError("budget-exceeded")
    return actions, by_id


BATCH_MAX_ITEMS = 128


def _invalid_batch():
    """Shape rejection for the batch envelope itself; `null` marks 'no element'.

    G4 keeps every envelope problem on this one code, including an unusable
    `limit`: the caller cannot fix a rejected envelope by retrying an element.
    """
    return {"status": "error", "error": "invalid-batch", "requestIndex": None,
            "results": [], "units": 0}


def _batch_failure(code, index):
    """Domain rejection attributed to one element; the whole batch fails with it.

    `index` is the element that actually failed -- `null` only for a batch-wide
    verdict such as `batch-limit-exceeded`, which no single element owns.
    """
    return {"status": "error", "error": code, "requestIndex": index,
            "results": [], "units": 0}


def _batch_body(item):
    """Reframe one element as a lone single-rollback request body.

    The journal already refused `action`, so `operation_id` is the only key that
    must not travel on: it is batch bookkeeping, not part of the rollback the
    single path validates, and leaving it in would make the batch element and
    the equivalent lone request diverge. Everything else is copied so the caller's
    objects are never mutated.
    """
    body = {key: value for key, value in item.items() if key in BATCH_ITEM_FIELDS
            and key != "operation_id"}
    body["action"] = "rollback"
    return body


def _batch_fingerprint(item):
    """Comparable identity of one element for retry detection.

    Compared against the *normalized* fields, not the raw object: absent keys are
    filled with their business defaults first, so `retain` omitted and
    `retain: []` are the same request, and an absent `depends_on` inside a change
    cannot fake a difference either. Inputs the journal accepts are shapes that
    read identically when re-validated, so normalizing through those same readers
    cannot invent a conflict.
    """
    return (item.get("environment"),
            item.get("budget"),
            read_changes(item.get("changes")),
            frozenset(read_applied(item.get("applied", []))),
            frozenset(read_retain(item, read_applied(item.get("applied", [])))))


def _read_batch_limit(request):
    """G4 `limit`: required nonnegative integer, booleans excluded.

    Lives here rather than in policy because the batch quota is batch-only: a
    single rollback has no ceiling and must not inherit this one. type() rather
    than isinstance() so `true`/`false` are not read as 1/0.
    """
    limit = request.get("limit")
    if type(limit) is not int or limit < 0:
        raise JournalError("invalid-batch")
    return limit


def rollback_many(request):
    """G4 batch rollback: one ordered list of independent single-rollback bodies.

    G4 splits G3's single pass in two places -- the element order is preserved
    and stays decisive, but the quota verdict moves to the very end:

    1. Envelope: only `action`/`limit`/`requests`, `limit` a nonnegative integer,
       `requests` an array of 1..128. Any breach is `invalid-batch` + null index.
    2. Every element, in request order, advances through its own layers *in
       place*: item shape and `operation_id` (`invalid-batch-item`), then
       repetition/conflict, then -- only for a first occurrence -- the G2 checks
       and the graph work. The first failing element wins with its own code and
       index, and the batch stops there. A later element's shape error therefore
       never outranks an earlier element's real domain error: CHANGE-G2.md:7
       fixes the order as "per request", so element 1 failing on
       `production-frozen` is reported before element 2 being malformed, and
       within one element shape still comes before repetition, which still comes
       before business.

    The identity check is therefore incremental: each element is registered the
    moment it is reached, and only a later repeat compares against it. Layer
    precedence inside one element is shape -> repetition/conflict -> business,
    and only the batch-wide `limit` verdict is deferred past every element.

    3. Envelope and element verdicts all resolved: the summed units of the
       non-retry results are compared with `limit`. Exceeding it is
       `batch-limit-exceeded` + null index; equal or below submits.

    Every map here is local to one call and no graph, closure or result is cached
    across elements, so two elements reusing IDs but differing in
    `applied`/`retain` cannot observe each other. Only the same `operation_id`
    with identical data is merged, and it is merged as the same operation.

    `request` may be any object at this point and non-objects are simply
    `invalid-batch`: the transport only routes objects labelled
    `rollback-many`, so a direct caller here is already talking batch language.
    """
    if not isinstance(request, dict):
        return _invalid_batch()
    # An element can never widen the batch's action, and the envelope cannot
    # smuggle batch-only keys past this gate, so the whitelist is exact.
    if not request.keys() <= {"action", "limit", "requests"}:
        return _invalid_batch()
    if request.get("action") != "rollback-many":
        return _invalid_batch()
    items = request.get("requests")
    if not isinstance(items, list) or not 1 <= len(items) <= BATCH_MAX_ITEMS:
        return _invalid_batch()
    try:
        limit = _read_batch_limit(request)
    except JournalError:
        return _invalid_batch()

    # One walk over `items` in request order: shape -> identity -> business per
    # element, so the first element to fail decides the code. Any pure
    # pre-scan would let a late malformed element hide an earlier domain error.
    # `seen` maps operation_id to the fingerprint that was accepted first, and it
    # only ever holds operations this batch has already validated in order.
    seen = {}
    results = []
    total = 0
    for index, item in enumerate(items):
        try:
            read_batch_item(item)
        except JournalError as exc:
            return _batch_failure(str(exc), index)
        operation_id = read_operation_id(item)
        try:
            # Identity compares normalized data (see `_batch_fingerprint`), so a
            # reordered object, or `retain` omitted vs `retain: []`, is a retry.
            fingerprint = _batch_fingerprint(item)
        except JournalError as exc:
            # Shape held but business data did not, so the comparison cannot be
            # made. Report this element's real domain code here rather than
            # guessing a conflict; a later repeat of the same ID cannot exist,
            # because it would have needed this element to register first.
            return _batch_failure(str(exc), index)
        previous = seen.get(operation_id)
        if previous is None:
            seen[operation_id] = fingerprint
        elif previous == fingerprint:
            # Retry: same ID, equivalent data. Nothing to add, nothing to charge.
            continue
        else:
            return _batch_failure("conflicting-operation", index)
        try:
            # Rollback by construction: the element's environment is still
            # checked (production stays frozen) and its budget is still
            # validated, but the plan quota never applies to a rollback.
            decision = rollback_decision(item)
            if decision.action != "rollback":
                raise PolicyError("unsupported-action")
            actions, by_id = compute_actions(_batch_body(item))
        except (PolicyError, JournalError) as exc:
            return _batch_failure(str(exc), index)
        # Retries never get here, so each accepted operation is priced once and
        # the running total is exactly the post-dedup cost `limit` is checked on.
        units = sum(by_id[key]["units"] for key in actions)
        results.append({"actions": actions, "units": units,
                        "operationId": operation_id})
        total += units

    # Last verdict: the batch-only quota. Reached only when every element has
    # already succeeded, so it can never hide a real failure.
    if total > limit:
        return _batch_failure("batch-limit-exceeded", None)
    return {"status": "ok", "results": results, "units": total}

